-- ESQUEMA COMPLETO MeGa Consultora
CREATE TABLE IF NOT EXISTS contratos (id SERIAL PRIMARY KEY, hoja TEXT, titulo TEXT, locador TEXT, locatario TEXT, vigencia_desde DATE, vigencia_hasta DATE, gastos_inicio NUMERIC, gastos_pagado NUMERIC, tipo_inmueble TEXT, modalidad_pago TEXT, periodicidad_actualizacion TEXT, indice_actualizacion TEXT, servicios_inquilino TEXT, propietario_id INTEGER, inquilino_id INTEGER, comision_porcentaje NUMERIC DEFAULT 8);
CREATE TABLE IF NOT EXISTS pagos (id SERIAL PRIMARY KEY, hoja TEXT, mes DATE, fecha_pago_hasta DATE, corresponde_a_mes DATE, importe_alquiler NUMERIC, impuestos_servicios NUMERIC, total NUMERIC, pagado TEXT, saldo NUMERIC, comision_8 NUMERIC, pago_nro TEXT, monto_epe NUMERIC, monto_agua NUMERIC, monto_tgiu NUMERIC, monto_seguro NUMERIC, monto_otros NUMERIC, concepto_otros TEXT, descuento_propietario NUMERIC);
CREATE TABLE IF NOT EXISTS personas (id SERIAL PRIMARY KEY, apellido TEXT, nombre TEXT, dni TEXT, cuit TEXT, domicilio TEXT, telefono TEXT, email TEXT, observaciones TEXT, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pagos_extras (id SERIAL PRIMARY KEY, pago_id INTEGER REFERENCES pagos(id) ON DELETE CASCADE, concepto TEXT, importe NUMERIC DEFAULT 0, a_cargo_de TEXT DEFAULT 'inquilino', tipo TEXT DEFAULT 'debito', created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS usuarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, nombre TEXT, aprobado BOOLEAN DEFAULT FALSE, admin BOOLEAN DEFAULT FALSE, rol TEXT DEFAULT 'admin', persona_id INTEGER, user_id TEXT, created_at TIMESTAMP DEFAULT NOW());
